import{Component,VisualJoint,materials}from'../../core/index.js';import{addCadParts}from'../../modeling/cad.js';import{printedArtwork}from'../../modeling/artwork.js';import{THREE,mesh,box,extrude,roundedRect,circleHole,annulus}from'./geometry.js';import data from'./geometry-data.js';import{spec}from'./dimensions.js';import{grove,usbC,microSD}from'./connectors.js';import{NativeButton}from'./NativeButton.js';
