 const indicators=[];for(const[x,c]of[[-1.4,0x922d28],[1.4,0xcccfc4]])indicators.push(box(host.body,[1.4,1,.6],[x,18.5,.3],materials.plastic(c),'U078-M12 internal nonemissive indicator carrier;external light path unconfirmed'));
 const switchBase=box(host.body,[5.3,2.2,3.8],[0,20.6,1.9],dark,'U078-M12 actual fixed internal top-end switch package envelope'),switchFrame=box(host.body,[5.5,1.7,.3],[0,20.6,3.95],metal,'U078-M12 fixed switch metal retainer'),switchTerminals=[];for(const x of[-2,2])for(const y of[19.8,21.4])switchTerminals.push(box(host.body,[.55,.65,.18],[x,y,.09],metal,'U078-M12 fixed switch solder terminal'));
 const follower=box(host.body,[2.5,.7,1.6],[0,22.05,1.3],materials.plastic(0xb7bcb0),'U078-M12 only actual internal switch plunger follows native tongue');
