function fanCarrier(host){const frame=new THREE.Group();frame.position.fromArray(spec.fan.position);frame.name='U078-M12 fixed concealed cooling assembly envelope;rotor not established';host.body.add(frame);const m=materials.plastic(0x202621,{roughness:.87}),housing=mesh(frame,annulus(7.1,5.7,1.8),m,[0,0,-1.6],'U078-M12 fixed fan surrounding carrier behind real native grille'),backing=mesh(frame,new THREE.CylinderGeometry(5.7,5.7,.7,48).rotateX(Math.PI/2),m,[0,0,-.95],'U078-M12 opaque retained cooling-unit backing seen through native grille'),hub=mesh(frame,new THREE.CylinderGeometry(2,2,1.4,40).rotateX(Math.PI/2),m,[0,0,-.6],'U078-M12 fixed concealed motor carrier envelope'),support=box(frame,[13,13,.8],[0,0,.4],materials.metal(0x5b6258),'U078-M12 fixed cooling assembly support beneath PCB');const posts=[];for(const x of[-5.8,5.8])for(const y of[-5.8,5.8])posts.push(mesh(frame,new THREE.CylinderGeometry(.6,.6,5,24).rotateX(Math.PI/2),m,[x,y,3.3],'U078-M12 inferred fixed cooling-to-PCB retaining spacer'));return{frame,housing,backing,hub,support,posts,rotor:null,joint:null};}
function label(host){const w=spec.label.size[0],h=spec.label.size[1],s=new THREE.Shape();s.moveTo(-w/2,h/2);s.lineTo(w/2,h/2);s.lineTo(w/2,-h/2);s.lineTo(6.4,-h/2);s.bezierCurveTo(4.4,-9.3,2.3,-9.3,0,-9.3);s.bezierCurveTo(-2.3,-9.3,-4.4,-9.3,-6.4,-h/2);s.lineTo(-w/2,-h/2);s.closePath();const film=mesh(host.body,extrude(s,.035),materials.plastic(0xeeeedd,{roughness:.86}),spec.label.position,'U078-M12 independent physical die-cut manufacturer adhesive film');film.userData={role:'physical-label-substrate',thicknessMm:.035,registrationInferred:true};const ink=printedArtwork(host,{target:film,url:rearUrl,size:spec.label.size,position:spec.label.position,face:'back',depth:.1,name:'U078-M12 own UNITV2 M12 readable rear manufacturer label redraw;variable identifiers omitted',artworkKind:'reference-redraw'});return{film,ink};}
function optics(host){const m=materials.plastic(0x131814,{roughness:.64}),green=materials.plastic(0x213d30),frame=new THREE.Group();frame.name='U078-M12 fixed optical installation';frame.position.set(0,9.75,0);host.body.add(frame);
 const supports=[];for(const x of[-6,6])for(const y of[-6,6])supports.push(box(frame,[1.2,1.2,3.2],[x,y,1.6],m,'U078-M12 inferred fixed optical PCB-to-board spacer'));
 const carrier=box(frame,[14.5,15,.8],[0,0,3.6],green,'U078-M12 retained GC2053 sensor subboard'),sensor=box(frame,[5.2,5.2,1],[0,0,4.5],materials.plastic(0x254f46),'U078-M12 fixed physical GC2053 package'),stop=mesh(frame,new THREE.CylinderGeometry(3.7,3.7,.35,48).rotateX(Math.PI/2),m,[0,0,5.18],'U078-M12 fixed deep optical stop behind real glass'),seat=mesh(frame,annulus(7.6,5.5,10.7),m,[0,0,4.0],'U078-M12 fixed M12 socket and light-tight sensor chamber');
 const flex=box(host.body,[7.4,14,.15],[0,-3.6,1.2],materials.plastic(0x9e812e),'U078-M12 inferred retained camera ribbon to main PCB');
 const turning=new THREE.Group();turning.name='U078-M12 actual manually rotatable lens barrel and optical glass';frame.add(turning);
 const barrel=mesh(turning,annulus(5.95,3.35,5.5),m,[0,0,14.7],'U078-M12 actual moving M12 barrel;thread pitch unconfirmed');
 const profile=[[6.8,20.1],[7,20.3],[7,23.7],[6.9,23.8],[3.35,22.8],[3.35,20.1],[6.8,20.1]].map(p=>new THREE.Vector2(...p));
 const rim=mesh(turning,new THREE.LatheGeometry(profile,72).rotateX(Math.PI/2),materials.plastic(0x151b18,{roughness:.43}),[0,0,0],'U078-M12 pictured broad adjustment rim and recessed conical optical mouth');
 const glass=mesh(turning,new THREE.SphereGeometry(3.26,48,32),materials.plastic(0x164746,{roughness:.14,metalness:.28}),[0,0,22.53],'U078-M12 real curved front optical glass');glass.scale.z=.105;
 const inner=mesh(turning,new THREE.CylinderGeometry(1.45,1.45,.3,48).rotateX(Math.PI/2),materials.plastic(0x245c50,{roughness:.15,metalness:.3}),[0,0,22.88],'U078-M12 central optical coating element');
 const focus=host.add(new VisualJoint({id:'focus',label:'Manual M12 lens · external visual angle',axis:spec.focus.axis,position:spec.focus.position,continuous:false,limitsDeg:null,meta:{visualRangeDeg:spec.focus.visualRangeDeg,role:'externally-driven-manual-focus',scope:'Only actual lens barrel/rim/glass rotate. Angle-only externally requested visual adjustment;no motor,RPM,autofocus,thread-pitch or axial/focal linkage.',angleSource:'Own official manual focus and own coaxial lens/drawing. No verified physical stops;visualRangeDeg is only a demo control interval,not measured travel.'}}));focus.adopt(turning);
 const anchor=host.add(new Component({id:'camera',label:'Fixed GC2053 optical axis anchor ·85°',position:spec.camera.position,meta:{role:'passive-optical-anchor',sensor:'GC2053',fovDeg:85,scope:'Fixed optical-axis datum only;no frames,display,capture,AI or readings. Selected documentary85deg optic;barrel dimensions reconstructed from own shared drawing.'}}));
 return{frame,supports,carrier,sensor,stop,seat,flex,turning,barrel,rim,glass,inner,focus,anchor};}
function acoustic(host){const can=box(host.body,[6.7,5.0,1.2],[6.6,-6.25,8.9],materials.metal(0x9b9f96),'U078-M12 retained acoustic carrier behind three native front slits;hidden install inferred'),backing=box(host.body,[6.8,5.1,.35],[6.6,-6.25,8.1],materials.plastic(0x202821),'U078-M12 opaque microphone carrier backing;no accidental through body view');const supports=[];for(const x of[4.1,9.1])supports.push(box(host.body,[.8,2,7.9],[x,-6.25,4.45],materials.plastic(0x26342b),'U078-M12 inferred microphone-to-PCB fixed retainer'));return{can,backing,supports};}
export function buildUnitV2M12(host,options=host.options){const opts={...spec.defaults,...options};if(opts.lens!=='85')throw new RangeError('UnitV2-M12 only independently reconstructed85deg lens is available');const parts=addCadParts(host,data,{shell:materials.plastic(0x252a25,{roughness:.86})}),front=parts[data[0].name],rear=parts[data[1].name];rear.material=materials.plastic(0x29302a,{roughness:.64,transparent:true,opacity:.78,depthWrite:false});const pcb=board(host),input=grove(host),usbc=usbC(host),storage=microSD(host),cooling=fanCarrier(host),user=host.add(new NativeButton(front,pcb.follower)),optical=optics(host),microphone=acoustic(host),labels=label(host);host.unitV2M12Assembly={parts,front,rear,board:pcb,input,usbc,storage,cooling,user,optical,microphone,labels,options:opts};host.unitStickers=labels.ink??[];}
